head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체. 
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: rowJSON, // 전달 데이터 객체. 
        name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
    };
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: 700 + "px",
        height: 400 + "px",
        top: 100 + "px",
        left: 100 + "px",
        popupName: "Test111",
        modal: true,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true,
        dataObject: dataObj
    };
    $p.openPopup("wframePopup_tabControl_tabScroll_WPFF-336_(WSQ-3879)_sub.xml", options);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById("popup1_wframe_wq_uuid_6_itemTable").children.length == 1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup1_wframe_wq_uuid_5_btn_submenu').click()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('popup1_wframe_wq_uuid_5_itemTable').style.visibility == 'visible'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
